import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,DUR,Easing,interpolate,clamp,FONT,Entrar,Destello} from './kit';
// DINERO 2026-11-28 18:00 — "El centavo que engaña" (9,99). 2.5D: Vol (luz y sombra), 3 capas con parallax, giro leve, sombras en el suelo.
// Protagonista que viaja: la etiqueta de precio 9,99. Personaje: Andrés. Todo sale de las palabras (T(i)), nada con segundos a mano.
export const SUBS={arriba:860,size:84,acento:'#FFC83D'};
type C3=[string,string,string];
const A=[0,8,24,40,65,94,112,137].map(T);
const AY=1230;
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const qo=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.out(Easing.cubic)});
const qb=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.out(Easing.back(1.9))});
const vis=(s:number,a:number,b:number,f=.2)=>interpolate(s,[a,a+f,b-f,b],[0,1,1,0],clamp);
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const SK:C3=['#f8d6b4','#d29767','#85502e'],SK2:C3=['#c98f65','#8a5532','#43250f'],SK3:C3=['#ffe6d0','#f2b08a','#a85d44'];
const HAIR:C3=['#5a5f6e','#1f222b','#06070a'],RED:C3=['#ff7b7b','#ff3b3b','#8a0f1a'],REDD:C3=['#ff5a5a','#c92632','#5e0912'];
const DK:C3=['#6a7390','#2a2e45','#0b0c18'],GOLD:C3=['#fff0b0','#ffc83d','#a86a00'],STEEL:C3=['#f4f8fc','#aab8c8','#5a6a80'];
// ---------- herramientas 2.5D (copiadas de la referencia aprobada)
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
// Volumen barato para piezas chicas (dedos, correas): degradado de luz arriba-izquierda a sombra abajo-derecha y borde fino.
const VG:React.FC<{id:string;d:string;c:C3;borde?:string}>=({id,d,c,borde})=><g>
 <defs><linearGradient id={id} x1='0' y1='0' x2='1' y2='1'><stop stopColor={c[0]}/><stop offset='.5' stopColor={c[1]}/><stop offset='1' stopColor={c[2]}/></linearGradient></defs>
 <path d={d} fill={`url(#${id})`} stroke={borde||c[2]} strokeWidth={3} strokeOpacity={.55} strokeLinejoin='round'/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Suelo:React.FC<{x:number;y:number;rx:number;ry:number;o?:number}>=({x,y,rx,ry,o=.38})=><ellipse cx={x} cy={y} rx={rx} ry={ry} fill='#000' opacity={o} filter='url(#b18)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.5'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <radialGradient id='iris' cx='.4' cy='.35'><stop stopColor='#d9a066'/><stop offset='.6' stopColor='#8a5028'/><stop offset='1' stopColor='#3a1a0a'/></radialGradient>
 <radialGradient id='cobre' cx='.35' cy='.3'><stop stopColor='#ffd2a8'/><stop offset='.55' stopColor='#d9803f'/><stop offset='1' stopColor='#7a3a12'/></radialGradient>
 <radialGradient id='luzBrain' cx='.5' cy='.45' r='.6'><stop stopColor='#bfe9ff' stopOpacity='.75'/><stop offset='1' stopColor='#6fb6ff' stopOpacity='0'/></radialGradient>
 <linearGradient id='haz' x1='0' x2='1'><stop stopColor='#00d1ff' stopOpacity='0'/><stop offset='.5' stopColor='#c8f6ff'/><stop offset='1' stopColor='#00d1ff' stopOpacity='0'/></linearGradient>
 <linearGradient id='vidrio' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#e8fbff'/><stop offset='1' stopColor='#a9dcef'/></linearGradient>
 <linearGradient id='cilindro' x1='0' x2='1'><stop stopColor='#2a2e45'/><stop offset='.3' stopColor='#e8edf5'/><stop offset='.7' stopColor='#8a95ad'/><stop offset='1' stopColor='#1b1e30'/></linearGradient>
 <linearGradient id='ruedaSombra' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#000' stopOpacity='.55'/><stop offset='.25' stopColor='#000' stopOpacity='0'/><stop offset='.75' stopColor='#000' stopOpacity='0'/><stop offset='1' stopColor='#000' stopOpacity='.55'/></linearGradient>
 <pattern id='peg' width='64' height='64' patternUnits='userSpaceOnUse'><circle cx='32' cy='32' r='6' fill='#04040c'/><circle cx='30' cy='30' r='2' fill='#5a6290' opacity='.5'/></pattern>
 <pattern id='ledp' width='7' height='7' patternUnits='userSpaceOnUse'><rect width='7' height='2.4' fill='#2a0000' opacity='.55'/></pattern>
</defs>;
// ---------- etiqueta de precio (la protagonista): cartulina amarilla con agujero y cordel, números gruesos con volumen
const TAGB='M-170 250L-100 130L100 130L170 250L170 580Q170 600 150 600L-150 600Q-170 600 -170 580Z';
type TagP={id:string;x:number;y:number;k?:number;r?:number;a?:string;b?:string;ca?:string;cb?:string;sa?:number;sb?:number;fa?:number;fb?:number;xa?:number;xb?:number;glow?:number;cord?:boolean;up?:number;body?:C3;sh?:boolean;children?:React.ReactNode};
const Tag:React.FC<TagP>=({id,x,y,k=1,r=0,a='9',b=',99',ca='#15110a',cb='#15110a',sa=1,sb=1,fa=200,fb=120,xa=-85,xb=75,glow=0,cord=true,up=0,body=['#fff3a8','#ffd23f','#b07a00'],sh=true,children})=>{
 const num=(t:string,xx:number,fs:number,sc:number,col:string)=><g transform={`translate(${xx} 440) scale(${sc}) translate(${-xx} -440)`}>
  <text x={xx+6} y={510} textAnchor='middle' fontFamily={FONT} fontWeight={900} fontSize={fs} fill='#7a4a00' opacity={.5}>{t}</text>
  <text x={xx} y={504} textAnchor='middle' fontFamily={FONT} fontWeight={900} fontSize={fs} fill={col}>{t}</text>
  <text x={xx-2} y={501} textAnchor='middle' fontFamily={FONT} fontWeight={900} fontSize={fs} fill='none' stroke='#fffbe0' strokeWidth={2} opacity={.45}>{t}</text></g>;
 return <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
  {glow>0&&<ellipse cy={420} rx={300} ry={340} fill='#ffc83d' opacity={glow*.5} filter='url(#b40)'/>}
  {sh&&<path d={TAGB} transform='translate(30 38)' fill='#000' opacity={.32} filter='url(#b18)'/>}
  {up>0&&<path d={caps(0,-up,0,0,9)} fill='#d8332f'/>}
  <VG id={id+'tb'} d={TAGB} c={body}/>
  <path d='M-150 252L-92 150L92 150L150 252' fill='none' stroke='#fffbe0' strokeWidth={5} opacity={.4}/>
  <circle cy={190} r={32} fill='#8a5a00' opacity={.6}/><circle cy={190} r={25} fill='#120c04'/>
  {cord&&<><path d={caps(0,0,-16,190,9)} fill='#d8332f'/><path d={caps(0,0,16,190,9)} fill='#ee5a4e'/>{up===0&&<circle r={12} fill='#c9d3e0' stroke='#5a6a80' strokeWidth={3}/>}</>}
  {children??<>{num(a,xa,fa,sa,ca)}{b!==''&&num(b,xb,fb,sb,cb)}</>}
  <Brillo2 x={-110} y={300} rx={14} ry={90} r={18} o={.45}/>
 </g>;
};
// ---------- persona (Andrés y las científicas): cabeza, orejas, cejas, ojos con iris y punto blanco, nariz con fosas, labios, cuello y ropa con volumen
type PerP={id:string;x:number;y:number;k?:number;s:number;skin?:C3;hair?:C3;style?:'fade'|'pony'|'curl';beard?:boolean;glasses?:boolean;coat?:boolean;look?:[number,number];sm?:number;open?:number;lid?:number;brow?:number;rot?:number;nobody?:boolean};
const Persona:React.FC<PerP>=({id,x,y,k=1,s,skin=SK,hair=HAIR,style='fade',beard=false,glasses=false,coat=false,look=[0,0],sm=0,open=0,lid=0,brow=0,rot=0,nobody=false})=>{
 const HEAD='M-135 -40C-145 -150 -80 -200 0 -200C80 -200 145 -150 135 -40C130 60 80 170 0 192C-80 170 -130 60 -135 -40Z';
 const cl:C3=coat?['#ffffff','#eaf0f8','#a3b2c8']:RED,cd:C3=coat?['#eaf0f8','#c4d0e0','#7a8aa3']:REDD;
 const lip=skin===SK2?'#7a2e2a':'#b04a42';
 const eye=(sg:number)=>{const cx=sg*58,cy=-30,cid=id+'ey'+(sg>0?1:0),d=`M${cx-36} ${cy}Q${cx} ${cy-32} ${cx+36} ${cy}Q${cx} ${cy+26} ${cx-36} ${cy}Z`;
  return <g key={sg}><defs><clipPath id={cid}><path d={d}/></clipPath></defs>
   <path d={d} fill='#fdfcf8'/>
   <g clipPath={`url(#${cid})`}>
    <circle cx={cx+look[0]} cy={cy+look[1]} r={17} fill='url(#iris)'/><circle cx={cx+look[0]} cy={cy+look[1]} r={8} fill='#0b0505'/>
    <circle cx={cx+look[0]-6} cy={cy+look[1]-7} r={5} fill='#fff'/><circle cx={cx+look[0]+7} cy={cy+look[1]+6} r={2.5} fill='#fff' opacity={.7}/>
    <rect x={cx-40} y={cy-40} width={80} height={12+lid*26} fill={skin[1]}/>
    <ellipse cx={cx} cy={cy-26} rx={40} ry={12} fill={skin[2]} opacity={.35} filter='url(#b6)'/>
   </g>
   <path d={`M${cx-37} ${cy+1}Q${cx} ${cy-34} ${cx+37} ${cy+1}`} fill='none' stroke='#25100a' strokeWidth={4.5} strokeLinecap='round'/>
   <path d={`M${cx-30} ${cy+8}Q${cx} ${cy+28} ${cx+30} ${cy+8}`} fill='none' stroke={skin[2]} strokeWidth={2.5} opacity={.45}/>
  </g>;};
 const yc=-sm*12,y1=3+sm*6,y2=y1+4+open*40+sm*10;
 const mouth=<g transform='translate(0 112)'>
  <path d={`M-46 ${yc}Q0 ${2*y1-yc} 46 ${yc}Q0 ${2*y2-yc} -46 ${yc}Z`} fill='#4a0c14'/>
  <defs><clipPath id={id+'mc'}><path d={`M-46 ${yc}Q0 ${2*y1-yc} 46 ${yc}Q0 ${2*y2-yc} -46 ${yc}Z`}/></clipPath></defs>
  {(sm>.3||open>.25)&&<g clipPath={`url(#${id}mc)`}><rect x={-46} y={y1-4} width={92} height={15} rx={5} fill='#fff'/><ellipse cx={0} cy={y2} rx={30} ry={10+open*8} fill='#c2455a'/></g>}
  <path d={`M-46 ${yc}Q0 ${2*y1-yc} 46 ${yc}`} fill='none' stroke={lip} strokeWidth={12} strokeLinecap='round'/>
  <path d={`M-44 ${yc+1}Q0 ${2*y2-yc+2} 44 ${yc+1}`} fill='none' stroke={lip} strokeWidth={16} strokeLinecap='round'/>
  <path d={`M-30 ${y2+7}Q0 ${y2+14} 30 ${y2+7}`} fill='none' stroke='#fff' strokeWidth={4} opacity={.28} strokeLinecap='round'/>
 </g>;
 return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
  {!nobody&&<>
   <VG id={id+'hb'} d={ell(0,236,175,80)} c={cd}/>
   <VG id={id+'nk'} d='M-62 120L-74 285Q0 340 74 285L62 120Z' c={skin}/>
   <ellipse cx={0} cy={168} rx={86} ry={36} fill={skin[2]} opacity={.5} filter='url(#b18)'/>
   <VG id={id+'bd'} d='M-345 800L-332 412Q-322 296 -170 262Q0 335 170 262Q322 296 332 412L345 800Z' c={cl}/>
   {coat?<>
    <VG id={id+'cs'} d='M-92 262L0 392L92 262Q0 330 -92 262Z' c={['#6fe0d0','#1fb5a5','#0a6a60']}/>
    <path d='M-92 262L-30 430L0 392' fill='none' stroke='#9aa9bf' strokeWidth={5}/><path d='M92 262L30 430L0 392' fill='none' stroke='#9aa9bf' strokeWidth={5}/>
    <VG id={id+'pl'} d='M170 520h86v52h-86Z' c={['#ffffff','#dfe8f3','#9aa9bf']}/>
   </>:<>
    <VG id={id+'cr'} d='M-98 252Q0 350 98 252Q86 312 0 332Q-86 312 -98 252Z' c={REDD}/>
    <VG id={id+'c1'} d={caps(-34,320,-40,452,10)} c={['#ffffff','#e6e6ee','#9a9aae']}/><VG id={id+'c2'} d={caps(34,320,40,462,10)} c={['#ffffff','#e6e6ee','#9a9aae']}/>
    <VG id={id+'hp'} d={caps(-150,455,-112,300,24)} c={DK}/><VG id={id+'hq'} d={caps(150,455,112,300,24)} c={DK}/>
    <VG id={id+'ha'} d='M-195 450Q-150 400 -105 450L-105 540Q-150 580 -195 540Z' c={DK}/><VG id={id+'hb2'} d='M195 450Q150 400 105 450L105 540Q150 580 195 540Z' c={DK}/>
    <ellipse cx={-150} cy={500} rx={24} ry={34} fill='#00D1FF' opacity={.55}/><ellipse cx={150} cy={500} rx={24} ry={34} fill='#ff2e93' opacity={.5}/>
   </>}
  </>}
  {style==='pony'&&<VG id={id+'pt'} d='M105 -150C230 -190 270 -70 215 40C190 100 170 130 152 108C195 20 185 -70 100 -112Z' c={['#ffb08a','#d65a24','#7a2208']}/>}
  <VG id={id+'e1'} d={ell(-139,10,22,38)} c={skin}/><VG id={id+'e2'} d={ell(139,10,22,38)} c={skin}/>
  <Vol id={id+'hd'} d={HEAD} c={skin} sw={80} o={26}/>
  {beard&&<VG id={id+'br'} d='M-136 10C-134 112 -80 192 0 196C80 192 134 112 136 10C122 60 96 84 66 98C40 74 -40 74 -66 98C-96 84 -122 60 -136 10Z' c={['#5a4a50','#2a2024','#0a0607']}/>}
  <Vol id={id+'ns'} d='M-12 -4Q-22 40 -36 54Q-30 74 0 76Q30 74 36 54Q22 40 12 -4Z' c={skin} sw={26} o={7}/>
  <ellipse cx={-16} cy={64} rx={9} ry={6} transform='rotate(-20 -16 64)' fill='#2a0e08'/><ellipse cx={16} cy={64} rx={9} ry={6} transform='rotate(20 16 64)' fill='#2a0e08'/>
  <Brillo2 x={-6} y={30} rx={5} ry={22} r={10} o={.4}/>
  {eye(-1)}{eye(1)}
  {[-1,1].map(sg=><path key={sg} d={caps(sg*58-sg*40,-88-brow*18+4,sg*58+sg*40,-88-brow*18-6,15)} fill={hair[1]}/>)}
  {mouth}
  {style==='fade'&&<>
   <VG id={id+'hr'} d='M-143 -45C-153 -172 -82 -226 0 -226C82 -226 153 -172 143 -45C132 -96 112 -132 70 -152C20 -168 -40 -168 -70 -152C-112 -132 -132 -96 -143 -45Z' c={hair}/>
   <path d='M-142 -42C-141 0 -137 24 -130 50L-118 14C-121 -26 -127 -62 -136 -86Z' fill='#2a2e3a' opacity={.55}/><path d='M142 -42C141 0 137 24 130 50L118 14C121 -26 127 -62 136 -86Z' fill='#2a2e3a' opacity={.55}/>
   <path d='M-60 -205Q-10 -222 40 -208' fill='none' stroke='#9aa0b4' strokeWidth={6} opacity={.5} strokeLinecap='round'/>
  </>}
  {style==='pony'&&<>
   <VG id={id+'hr'} d='M-146 -35C-156 -178 -84 -228 0 -228C84 -228 156 -178 146 -35C140 -80 118 -120 72 -138C30 -112 -50 -112 -80 -135C-118 -118 -138 -80 -146 -35Z' c={['#ffb08a','#d65a24','#7a2208']}/>
   <VG id={id+'bn'} d={ell(122,-128,16,26)} c={['#8ef0e0','#1fb5a5','#0a6a60']}/>
  </>}
  {style==='curl'&&<g>{[-120,-90,-55,-15,25,65,100,128].map((cx,j)=><VG key={j} id={id+'cu'+j} d={ell(cx,-132-Math.abs(cx)*-.18-(j%2?14:0)+Math.abs(cx)*.2,52,50)} c={['#6a4a3a','#2e1c14','#0c0604']}/>)}
   <VG id={id+'cm'} d={ell(0,-165,110,58)} c={['#6a4a3a','#2e1c14','#0c0604']}/></g>}
  {glasses&&<g>{[-1,1].map(sg=><g key={sg}><rect x={sg*58-50} y={-56} width={100} height={66} rx={24} fill='#bfeaff' opacity={.14}/><rect x={sg*58-50} y={-56} width={100} height={66} rx={24} fill='none' stroke='#1b1b26' strokeWidth={7}/></g>)}
   <path d='M-12 -34Q0 -46 12 -34' fill='none' stroke='#1b1b26' strokeWidth={7}/><Brillo2 x={-84} y={-46} rx={14} ry={5} r={-30} o={.8}/></g>}
  <Brillo2 x={-70} y={-120} rx={34} ry={9} r={-20} o={.35}/>
 </g>;
};
// ---------- mano con volumen: palma, nudillos, dedos de dos tramos y uñas (nunca trazos sueltos)
const Mano:React.FC<{id:string;x:number;y:number;k?:number;r?:number;v?:'pinch'|'point'|'thumb';manga?:C3;arm?:number}>=({id,x,y,k=1,r=0,v='pinch',manga=RED,arm=900})=>{
 const off=v==='point'?[34,130]:v==='thumb'?[-30,74]:[-4,0];
 const dd=(n:C3)=>[n[1],n[2],n[2]] as C3;
 return <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k}) translate(${off[0]} ${off[1]})`}>
  <VG id={id+'sl'} d={caps(26,300,48,arm,150)} c={manga}/>
  <VG id={id+'cf'} d={caps(22,296,28,334,168)} c={dd(manga)}/>
  <VG id={id+'mn'} d={caps(8,230,22,312,100)} c={SK}/>
  <VG id={id+'pm'} d='M-68 120C-76 70 -58 40 -30 34L50 34C84 44 92 100 80 160C72 230 40 270 8 272C-30 268 -66 220 -68 120Z' c={SK}/>
  {v==='thumb'?<>
   {[70,108,146,184].map((yy,j)=><VG key={j} id={id+'f'+j} d={caps(-52,yy,60,yy+6,38)} c={SK}/>)}
   <VG id={id+'t1'} d={caps(30,60,30,-50,50)} c={SK}/>
   <VG id={id+'n1'} d={ell(30,-66,13,10)} c={['#fff4ec','#f4d8c8','#d9a890']}/>
   {[-40,-5,30].map((cx,j)=><Brillo2 key={j} x={cx} y={72+j*2} rx={9} ry={5} r={-20} o={.55}/>)}
  </>:<>
   {[[-30,68,-58,118],[6,70,-26,128],[40,80,12,134]].map((p,j)=><VG key={j} id={id+'cu'+j} d={caps(p[0],p[1],p[2],p[3],34)} c={SK}/>)}
   {v==='pinch'?<>
    <VG id={id+'i1'} d={caps(-40,70,-34,22,36)} c={SK}/><VG id={id+'i2'} d={caps(-34,22,-8,-6,32)} c={SK}/>
    <VG id={id+'h1'} d={caps(70,170,60,100,44)} c={SK}/><VG id={id+'h2'} d={caps(60,100,16,6,38)} c={SK}/>
    <VG id={id+'u1'} d={ell(-10,-3,8,6)} c={['#fff4ec','#f4d8c8','#d9a890']}/><VG id={id+'u2'} d={ell(18,6,9,6)} c={['#fff4ec','#f4d8c8','#d9a890']}/>
   </>:<>
    <VG id={id+'i1'} d={caps(-40,70,-38,-30,36)} c={SK}/><VG id={id+'i2'} d={caps(-38,-30,-34,-130,32)} c={SK}/>
    <VG id={id+'u1'} d={ell(-34,-124,8,11)} c={['#fff4ec','#f4d8c8','#d9a890']}/>
    <VG id={id+'h1'} d={caps(70,170,52,112,44)} c={SK}/><VG id={id+'h2'} d={caps(52,112,22,92,38)} c={SK}/>
   </>}
   {[-36,-4,28,56].map((cx,j)=><Brillo2 key={j} x={cx} y={50+j*3} rx={9} ry={5} r={-20} o={.6}/>)}
  </>}
 </g>;
};
